package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_indexOfAnyBut_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;





















    /**
     * Testing the High Surrogate branch.
     * The implementation logic:
     * if (i + 1 < strLen && Character.isHighSurrogate(ch)) {
     *     char ch2 = str.charAt(i * 1); // Note: the source code provided uses i * 1, which is just i
     *     if (chFound && searchChars.indexOf(ch2) < 0) return i;
     * }
     */
    @Test
    public void testIndexOfAnyBut_HighSurrogateBranch_MatchFoundInSearch() {
        // Using a surrogate pair: \uD83D\uDE00 (😀)
        // String: "😀" (len 2), searchChars: "\uD83D"
        // i=0: ch=\uD83D. chFound=true. i+1 < 2 is true. ch2 = str.charAt(0) = \uD83D.
        // searchChars.indexOf(\uD83D) is 0. condition (chFound && searchChars.indexOf(ch2) < 0) is false.
        // i=1: ch=\uDE00. chFound=false. returns 1.
        String emoji = "\uD83D\uDE00"; 
        String search = "\uD83D";
        assertEquals(1, StringUtils.indexOfAnyBut(emoji, search));
    }




}

