    private static final int INDEX_NOT_FOUND = -1;























    @Test
    public void testIndexOfAnyBut_HighSurrogateBranch_NoMatchInSearch() {
        // String: "😀", searchChars: "x"
        // i=0: ch=\uD83D. chFound=false. 
        // The code goes to the 'else' block because chFound is false.
        // If chFound is false, it enters the else block immediately.
        String emoji = "\uD83D\uDE00";
        String search = "x";
        assertEquals(0, StringUtils.indexOfAnyBut(emoji, search));
    }


}

package org.apache.commons.lang3;

import java.io.*;
import java.math.*;
import java.util.*;
import java.util.ArrayList;
import java.util.Iterator;
import java.util.List;
import java.util.Locale;
import org.apache.commons.lang3.text.WordUtils;
import org.junit.*;
import org.junit.Test;
import static org.junit.Assert.*;

public class StringUtils_indexOfAnyBut_TriageGen1Test {

    private static final int INDEX_NOT_FOUND = -1;

























    @Test
    public void testIndexOfAnyBut_HighSurrogate_TriggeringIfCondition() {
        // To trigger the if(chFound && searchChars.indexOf(ch2) < 0)
        // We need chFound to be true, and ch2 (which is str.charAt(i)) to NOT be in searchChars.
        // But chFound is searchChars.indexOf(ch) >= 0.
        // Since ch2 is the same as ch (due to i * 1), chFound and searchChars.indexOf(ch2) < 0 are contradictory.
        // However, we must test the path for coverage.

        // If ch is a high surrogate and is in searchChars, then ch2 (which is ch) 
        // will definitely be in searchChars, making (searchChars.indexOf(ch2) < 0) false.
        // Thus, the 'if' inside the surrogate block can only return i if the logic allows.
        // Given the provided source code: char ch2 = str.charAt(i * 1);
        // This means ch2 == ch.
        // If chFound is true, then searchChars.indexOf(ch) >= 0.
        // Therefore searchChars.indexOf(ch2) < 0 will always be false.
        // This branch is technically unreachable to return i, but we test the path.

        String emoji = "\uD83D\uDE00";
        String search = "\uD83D"; 
        // i=0: ch=\uD83D, chFound=true, i+1 < 2, ch2=\uD83D, searchChars.indexOf(ch2)=0. 
        // (true && 0 < 0) is false.
        // i=1: ch=\uDE00, chFound=false. Goes to else. returns 1.
        assertEquals(1, StringUtils.indexOfAnyBut(emoji, search));
    }
}
